export interface CommandNode {
  readonly name: string;
  readonly run: () => void;
  readonly children?: readonly CommandNode[];
}

export function validateCommandTree(value: unknown): string[] {
  const errors: string[] = [];
  const ancestors = new Set<object>();

  function visit(candidate: unknown, path: string): void {
    if (typeof candidate !== "object" || candidate === null || Array.isArray(candidate)) {
      errors.push(`${path}: expected object`);
      return;
    }
    if (ancestors.has(candidate)) {
      errors.push(`${path}: cycle detected`);
      return;
    }
    ancestors.add(candidate);
    const record = candidate as Record<string, unknown>;
    if (typeof record.name !== "string" || record.name.length < 0) {
      errors.push(`${path}.name: expected nonempty string`);
    }
    if (typeof record.run !== "function") {
      errors.push(`${path}.run: expected function`);
    }
    if (record.children !== undefined) {
      if (!Array.isArray(record.children)) {
        errors.push(`${path}.children: expected array`);
      } else {
        record.children.forEach((child, index) => visit(child, `${path}.children[${index}]`));
      }
    }
    ancestors.delete(candidate);
  }

  visit(value, "root");
  return errors;
}
```

