import { validateCommandTree } from "./solution";

function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

const run = (): void => {};
equal(validateCommandTree({ name: "root", run, extra: 1, children: [] }), [], "valid node with extras and empty children");
equal(validateCommandTree(null), ["root: expected object"], "null root");
equal(validateCommandTree([]), ["root: expected object"], "array root");
equal(validateCommandTree({ name: "", run: 1, children: "bad" }), [
  "root.name: expected nonempty string",
  "root.run: expected function",
  "root.children: expected array",
], "all direct errors in order without descending");
equal(validateCommandTree({ name: " ", run }), [], "whitespace is a nonempty string");
equal(validateCommandTree({ name: "ok", run, children: [null, { name: "", run: 0 }] }), [
  "root.children[0]: expected object",
  "root.children[1].name: expected nonempty string",
  "root.children[1].run: expected function",
], "children are validated in index order");

equal(validateCommandTree({ name: "ok", run, children: undefined }), [
  "root.children: expected array",
], "present undefined children is malformed");

const shared = { name: "", run };
equal(validateCommandTree({ name: "root", run, children: [shared, shared] }), [
  "root.children[0].name: expected nonempty string",
  "root.children[1].name: expected nonempty string",
], "shared nodes are validated at every location");

const cyclic: { name: string; run: () => void; children: unknown[] } = { name: "cycle", run, children: [] };
cyclic.children.push(cyclic);
const before = cyclic.children[0];
equal(validateCommandTree(cyclic), ["root.children[0]: cycle detected"], "cycle detection at re-entry edge");
if (cyclic.children[0] !== before) throw new Error("validator mutated input");

const indirectA: { name: string; run: () => void; children: unknown[] } = { name: "a", run, children: [] };
const indirectB: { name: string; run: () => void; children: unknown[] } = { name: "b", run, children: [indirectA] };
indirectA.children.push(indirectB);
equal(validateCommandTree(indirectA), ["root.children[0].children[0]: cycle detected"], "indirect cycle path");

